+import type { KeyVaultSecret, SecretClient } from "@azure/keyvault-secrets";
+
+export interface SecretValue {
+  name: string;
+  value: string;
+  version?: string;
+  expiresOn?: Date;
+  usedDefault: boolean;
+}
+
+export interface SecretLookup {
+  name: string;
+  defaultValue: string;
+  version?: string;
+}
